set -Eeuo pipefail
sudo -n /usr/bin/python3 - <<'PY'
from pathlib import Path
import subprocess,os,json,time
root=Path('/srv/projects/telegram-robot-leads')
old=Path('/opt/telegram-robot-leads')
config=root/'ecosystem.config.js'
recovery=root/'.pm2-path-cutover-recover.config.cjs'
vault=Path('/root/project-secrets/telegram-robot-leads')
def cmd(args,t=35):
 return subprocess.run(args,capture_output=True,text=True,timeout=t)
def current():
 p=cmd(['pm2','jlist'],15)
 if p.returncode:raise RuntimeError('PM2 jlist failed')
 return [x for x in json.loads(p.stdout) if x.get('name') in ('iptvpn_bot','telegram-robot-leads')]
def find(items,name):
 matches=[x for x in items if x.get('name')==name]
 if len(matches)!=1:raise RuntimeError('Expected one '+name)
 x=matches[0];env=x.get('pm2_env') or {}
 return {'pid':x.get('pid'),'status':env.get('status'),'cwd':env.get('pm_cwd'),'script':env.get('pm_exec_path'),'interpreter':env.get('exec_interpreter')}
if not root.is_dir() or root.is_symlink() or not old.is_symlink() or old.resolve()!=root:raise RuntimeError('Canonical root and old alias missing')
if not config.is_file() or recovery.exists() or recovery.is_symlink():raise RuntimeError('Unexpected app/recovery config')
if not (root/'.venv/bin/python').exists():raise RuntimeError('Project Python interpreter missing')
if not vault.is_dir() or vault.is_symlink():raise RuntimeError('Private vault missing')
sessions=sorted(vault.glob('*.session'))
if len(sessions)!=2:raise RuntimeError('Unexpected session count')
sessions_before={x.name:(x.stat().st_ino,x.stat().st_size,x.stat().st_mtime_ns) for x in sessions}
initial=current()
bot=find(initial,'telegram-robot-leads')
other=find(initial,'iptvpn_bot')
if bot['status']!='online' or bot['cwd']!=str(old) or other['status']!='online':raise RuntimeError('PM2 baseline not expected')
if bot['script']!=str(old/'main.py'):raise RuntimeError('Bot entrypoint differs from expected')
source=config.read_text()
if '"/srv/projects/telegram-robot-leads"' not in source or str(vault) not in source:raise RuntimeError('Canonical ecosystem config mismatch')
old_source=source.replace('/srv/projects/telegram-robot-leads',str(old))
if old_source==source:raise RuntimeError('Failed to derive recovery config')
print('PM2_BEFORE_CWD='+str(bot['cwd']))
print('PM2_BEFORE_PID='+str(bot['pid']))
print('IPTVPN_PROTECTED_PID='+str(other['pid']))
created=False
deleted_old=False
try:
 fd=os.open(recovery,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(fd,'w') as f:f.write(old_source);f.flush();os.fsync(f.fileno())
 created=True
 if cmd(['node','--check',str(config)],14).returncode or cmd(['node','--check',str(recovery)],14).returncode:raise RuntimeError('PM2 config syntax check failed')
 p=cmd(['pm2','delete','telegram-robot-leads'],30)
 if p.returncode:
  print('PM2_DELETE_ERROR_CLASS='+p.stderr.strip()[:210])
  raise RuntimeError('Could not stop previous targeted PM2 worker')
 deleted_old=True
 p=cmd(['pm2','start',str(config),'--only','telegram-robot-leads','--update-env'],45)
 if p.returncode:
  print('PM2_START_ERROR_CLASS='+p.stderr.strip()[:230])
  raise RuntimeError('Canonical worker could not start')
 for t in range(4):
  time.sleep(2)
  now=current()
  b=find(now,'telegram-robot-leads')
  if b['status']=='online' and b['cwd']==str(root) and b['script']==str(root/'main.py'):
   break
  print('POLL',t+1,'STATUS',str(b['status']),'CWD',str(b['cwd']),'SCRIPT',str(b['script']))
 else:raise RuntimeError('Canonical worker not online after restart')
 if find(now,'iptvpn_bot')!=other:raise RuntimeError('Unrelated IPTV PN bot changed')
 for p in sessions:
  if (p.stat().st_ino,p.stat().st_size,p.stat().st_mtime_ns)!=sessions_before[p.name]:raise RuntimeError('Session file changed during cutover')
 if cmd(['pm2','save'],30).returncode:raise RuntimeError('Cannot save new PM2 boot configuration')
except Exception as error:
 print('TARGETED_CUTOVER_FAILED='+str(error)[:280])
 if deleted_old:
  cur=current()
  if any(x.get('name')=='telegram-robot-leads' for x in cur):
   rem=cmd(['pm2','delete','telegram-robot-leads'],25)
   print('ROLLBACK_CLEANUP_RC='+str(rem.returncode))
  p=cmd(['pm2','start',str(recovery),'--only','telegram-robot-leads','--update-env'],45)
  print('ROLLBACK_RESTART_RC='+str(p.returncode))
  if p.returncode==0:
   time.sleep(2)
   check=find(current(),'telegram-robot-leads')
   print('ROLLBACK_BOT_STATUS='+str(check['status'])+';CWD='+str(check['cwd']))
   restored=cmd(['pm2','save'],28)
   print('ROLLBACK_SAVE_RC='+str(restored.returncode))
 raise
finally:
 if created and recovery.is_file() and not recovery.is_symlink():recovery.unlink()
print('NEW_TELEGRAM_BOT_PID='+str(b['pid']))
print('NEW_TELEGRAM_BOT_CWD='+str(b['cwd']))
print('NEW_TELEGRAM_BOT_SCRIPT='+str(b['script']))
print('IPTVPN_BOT_PID_UNCHANGED='+str(other['pid']))
print('SESSIONS_INODES_SIZES_MTIMES_UNCHANGED=YES')
print('PM2_SAVE=PASS')
print('PM2_PATH_CANONICALIZED=PASS')
PY
